function loadState(){try{const saved=JSON.parse(localStorage.getItem(STORE_KEY));if(saved&&Array.isArray(saved.visits)){saved.visits.forEach(v=>(v.activity||[]).forEach(a=>{if(a.actor==='Monse Caron')a.actor='Monserrat Jimenez';}));return saved;}}catch(e){}return seedData();}
let state=loadState();
let page={name:'overview',visitId:null,tab:'Overview',view:'list',filter:'All statuses',search:'',onlyReview:false,month:new Date(new Date().getFullYear(),new Date().getMonth(),1)};
let modalSubmit=null;
const appContent=document.getElementById('appContent');
function persist(){try{localStorage.setItem(STORE_KEY,JSON.stringify(state));updateNav();return true;}catch(e){toast('Browser storage is full. Remove a large attachment and try again.',true);return false;}}
function updateNav(){const live=state.visits.filter(v=>!v.archived);document.getElementById('navVisitCount').textContent=live.length;document.getElementById('navReviewCount').textContent=live.reduce((n,v)=>n+reviewCount(v),0);document.getElementById('roleSelect').value=state.role||'SUPER_ADMIN';const activePage=page.onlyReview?'needs-review':page.name==='detail'?(state.visits.find(v=>v.id===page.visitId)?.archived?'archives':'all-visits'):page.name;document.querySelectorAll('[data-nav-page]').forEach(link=>{const active=link.dataset.navPage===activePage;link.classList.toggle('active',active);link.setAttribute('aria-current',active?'page':'false');});}
function esc(value=''){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function person(id){return people.find(p=>p.id===id)||{id:'',name:'Unassigned',initials:'—',role:''};}
function personName(id){return person(id).name;}
function currentUserId(){return state.role==='VP'?'marc':state.role==='SALES'?'nina':'monse';}
function canView(v){if(state.role==='SUPER_ADMIN')return true;const id=currentUserId();return v.lead===id||v.collaborators.includes(id)||v.sales.includes(id);}
function reviewCount(v){return v.bookings.filter(b=>b.needsReview).length;}
function activeBookings(v,type){return v.bookings.filter(b=>(!type||b.type===type)&&b.status!=='Cancelled');}
function progress(v,type){const list=activeBookings(v,type);return list.length?Math.round(list.filter(b=>b.status==='Done').length/list.length*100):null;}
function fmtDate(s, options={month:'short',day:'numeric'}){if(!s)return '—';const d=new Date(`${s}T12:00:00`);return new Intl.DateTimeFormat('en-US',options).format(d);}
function fmtRange(start,end){if(!start&&!end)return 'Dates to be confirmed';if(start&&end){const a=new Date(`${start}T12:00:00`),b=new Date(`${end}T12:00:00`);if(a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth())return `${fmtDate(start)} – ${fmtDate(end,{day:'numeric'})}`;return `${fmtDate(start,{month:'short',day:'numeric',year:'numeric'})} – ${fmtDate(end,{month:'short',day:'numeric',year:'numeric'})}`;}return fmtDate(start||end,{month:'short',day:'numeric',year:'numeric'});}
function statusClass(status){return `status-${status.toLowerCase().replaceAll(' ','-')}`;}
function statusPill(status){return `<span class="status-pill ${statusClass(status)}">${esc(status)}</span>`;}
function themeClass(v){return ({terracotta:'thumb-terracotta',blue:'thumb-blue',sage:'thumb-sage',night:'thumb-night'})[v.theme]||'';}
function iconFor(type){return ({Flight:'✈',Hotel:'⌂',Transportation:'↗',Restaurant:'◌',Activity:'✳'})[type]||'•';}
function personAvatar(id){const p=person(id);return `<span class="mini-avatar" title="${esc(p.name)}">${esc(p.initials)}</span>`;}
function guestAvatar(g){return `<span class="mini-avatar" title="${esc(g.firstName+' '+g.lastName)}">${esc((g.firstName[0]||'')+(g.lastName[0]||''))}</span>`;}
function log(v,action,detail){v.activity.unshift({id:uid(),actor:state.role==='SUPER_ADMIN'?'Monserrat Jimenez':person(state.role==='VP'?v.lead:'nina').name,action,detail,at:new Date().toISOString()});}
function canEdit(v){if(state.role==='SUPER_ADMIN')return true;if(state.role==='SALES'||['Completed','Cancelled'].includes(v.status))return false;const id=currentUserId();return v.lead===id||v.collaborators.includes(id);}
function canManageBookingStatus(){return state.role==='SUPER_ADMIN';}
function categoryCounts(v,type){return bookingStatuses.map(s=>[s,v.bookings.filter(b=>b.type===type&&b.status===s).length]);}
function sortedVisits(list){return [...list].sort((a,b)=>(a.startDate||'9999').localeCompare(b.startDate||'9999'));}

function dashboardItems(){
  const archived=page.name==='archives';
  let items=state.visits.filter(v=>!!v.archived===archived&&canView(v));
  if(page.filter!=='All statuses')items=items.filter(v=>v.status===page.filter);
  if(page.onlyReview)items=items.filter(v=>reviewCount(v)>0);
  if(page.search){const q=page.search.toLowerCase();items=items.filter(v=>`${v.name} ${v.city} ${v.country} ${personName(v.lead)}`.toLowerCase().includes(q));}
  return sortedVisits(items);
}
function renderDashboard(){
  const archived=page.name==='archives', overview=page.name==='overview'&&!page.onlyReview, allVisits=page.name==='all-visits', visits=dashboardItems();
  const live=state.visits.filter(v=>!v.archived&&canView(v)), upcoming=live.filter(v=>['Upcoming','In Progress'].includes(v.status)), needing=live.reduce((n,v)=>n+reviewCount(v),0), guestTotal=live.reduce((n,v)=>n+v.guests.filter(g=>g.status!=='Cancelled').length,0);
  const overviewVisits=sortedVisits(live.filter(v=>['Planning','Upcoming','In Progress'].includes(v.status))).slice(0,4);
  const title=archived?'Archived visits':page.onlyReview?'Needs review':page.name==='settings'?'Workspace settings':overview?'Overview':allVisits?'All visits':'Your visits';
  document.getElementById('breadcrumbCurrent').textContent=title;
  appContent.innerHTML=`<div class="page-heading"><div><p class="eyebrow">${archived?'THE ARCHIVE':page.onlyReview?'ATTENTION REQUIRED':overview?"YOUR WORKSPACE":new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric'}).format(new Date()).toUpperCase()}</p><h1>${title}</h1><p class="page-subtitle">${archived?'Past plans, kept close at hand.':page.onlyReview?'A quick look at the details that need a second look.':overview?'A snapshot of upcoming visits and the details that need attention.':page.name==='settings'?'Manage this local demo workspace.':`Browse and filter every active customer visit.`}</p></div>${state.role==='SUPER_ADMIN'&&!archived&&!page.onlyReview&&page.name!=='settings'?`<button class="primary-button" data-action="new-visit"><span class="plus">+</span> Create a visit</button>`:''}</div>
    ${page.name==='settings'?renderSettings():`${overview?`<section class="stats-grid">
      <div class="stat-card"><div class="stat-top"><span class="stat-label">Active visits</span><span class="stat-icon coral">▤</span></div><div class="stat-number">${live.length}<span class="stat-foot">on your board</span></div><i class="stat-hairline"></i></div>
      <div class="stat-card"><div class="stat-top"><span class="stat-label">Coming up</span><span class="stat-icon blue">↗</span></div><div class="stat-number">${upcoming.length}<span class="stat-foot">next 30 days</span></div><i class="stat-hairline" style="width:52%;background:linear-gradient(90deg,#819cb7,#c8d9e3)"></i></div>
      <div class="stat-card"><div class="stat-top"><span class="stat-label">Guests</span><span class="stat-icon green">♧</span></div><div class="stat-number">${guestTotal}<span class="stat-foot">across all visits</span></div><i class="stat-hairline" style="width:64%;background:linear-gradient(90deg,#86ae93,#cde1d2)"></i></div>
      <div class="stat-card"><div class="stat-top"><span class="stat-label">Needs review</span><span class="stat-icon gold">◉</span></div><div class="stat-number">${needing}<span class="stat-foot">bookings flagged</span></div><i class="stat-hairline" style="width:${needing?38:0}%;background:linear-gradient(90deg,#e5a276,#f4d1b8)"></i></div>
    </section>`:''}
    <div class="dashboard-grid ${overview?'overview-dashboard':''} ${allVisits&&!page.onlyReview?'all-visits-dashboard':''}"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">${overview?'Upcoming visits':archived?'Archived visits':page.onlyReview?'Bookings to review':'Visit schedule'}</h2><p class="panel-caption">${overview?`${overviewVisits.length} upcoming ${overviewVisits.length===1?'visit':'visits'} · next on your calendar`:archived?'Your completed and paused plans':`${visits.length} ${visits.length===1?'visit':'visits'} · updated just now`}</p></div>${overview?`<button class="small-link" data-action="all-visits">View all visits →</button>`:allVisits&&!page.onlyReview?`<div class="view-switch"><button data-view="list" class="${page.view==='list'?'active':''}">☷ &nbsp;List</button><button data-view="calendar" class="${page.view==='calendar'?'active':''}">▦ &nbsp;Calendar</button></div>`:''}</div>
      ${allVisits||archived||page.onlyReview?renderToolbar(archived):''}${overview?renderVisitTable(overviewVisits,false):page.view==='calendar'&&allVisits&&!page.onlyReview?renderCalendar(visits):renderVisitTable(visits,archived)}
      ${overview?`<div class="table-footer"><span>Next customer visits</span><button class="small-link" data-action="all-visits">See all ${live.length} visits →</button></div>`:visits.length?`<div class="table-footer"><span>Showing <b>${visits.length}</b> ${visits.length===1?'visit':'visits'}</span><span>${archived?`<button class="small-link" data-action="all-visits">Back to active visits →</button>`:'Your workspace · Eastern Time'}</span></div>`:''}</section>
      ${overview?renderSideStack(live):allVisits&&!page.onlyReview?'':`<aside class="side-stack">${renderQuickGuide()}</aside>`}</div>`}`;
  updateNav();
}
function renderToolbar(archived){return `<div class="visit-toolbar"><label class="search-box"><svg viewBox="0 0 24 24"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></svg><input id="visitSearch" placeholder="Search visits or destinations" value="${esc(page.search)}" /></label><select class="filter-select" id="statusFilter"><option>All statuses</option>${visitStatuses.map(s=>`<option ${page.filter===s?'selected':''}>${s}</option>`).join('')}</select>${!archived?`<label class="filter-check"><input id="reviewFilter" type="checkbox" ${page.onlyReview?'checked':''}> Needs review</label>`:''}</div>`;}
function renderVisitTable(visits,archived){
 if(!visits.length)return `<div class="empty-state"><div class="empty-symbol">${archived?'▣':'◌'}</div><h3>${archived?'Nothing archived yet':'No visits match this view'}</h3><p>${archived?'Visits you archive will stay here, ready to restore.':'Try another filter or start planning a new customer visit.'}</p>${state.role==='SUPER_ADMIN'&&!archived&&!page.onlyReview?`<button class="primary-button" data-action="new-visit"><span class="plus">+</span> Create a visit</button>`:''}</div>`;
 return `<div class="mobile-visit-list" aria-label="Visits">${visits.map(v=>`<article class="mobile-visit-card" role="button" tabindex="0" data-open-visit="${v.id}"><div class="mobile-visit-card-head"><div class="visit-name"><span class="visit-thumb ${themeClass(v)}"></span><span><strong>${esc(v.name)}</strong><small>${v.guests.filter(g=>g.status!=='Cancelled').length} guests · ${v.bookings.length} bookings</small></span></div>${statusPill(v.status)}</div><div class="mobile-visit-card-details"><div><span>Destination</span><strong>${v.city?`${esc(v.city)}, ${esc(v.country)}`:'Not set'}</strong></div><div><span>Dates</span><strong>${fmtRange(v.startDate,v.endDate)}</strong></div><div><span>Lead VP</span><strong class="mobile-visit-lead">${personAvatar(v.lead)}${esc(personName(v.lead).split(' ')[0])}</strong></div></div>${reviewCount(v)?`<span class="review-badge">${reviewCount(v)} to review</span>`:''}<span class="mobile-visit-open" aria-hidden="true">View visit <b>›</b></span></article>`).join('')}</div><div class="table-wrap"><table class="visit-table"><thead><tr><th>Visit</th><th>Destination</th><th>Dates</th><th>Lead VP</th><th>Status</th><th>Needs review</th><th></th></tr></thead><tbody>${visits.map(v=>`<tr data-open-visit="${v.id}"><td><div class="visit-name"><span class="visit-thumb ${themeClass(v)}"></span><span><strong>${esc(v.name)}</strong><small>${v.guests.filter(g=>g.status!=='Cancelled').length} guests · ${v.bookings.length} bookings</small></span></div></td><td class="destination-cell">${v.city?`${esc(v.city)}, ${esc(v.country)}`:'<span class="review-empty">Not set</span>'}</td><td class="date-cell">${fmtRange(v.startDate,v.endDate)}</td><td><span class="lead-cell">${personAvatar(v.lead)}${esc(personName(v.lead).split(' ')[0])}</span></td><td>${statusPill(v.status)}</td><td>${reviewCount(v)?`<span class="review-badge">${reviewCount(v)} to review</span>`:'<span class="review-empty">—</span>'}</td><td><button class="row-menu" data-row-menu="${v.id}" aria-label="Visit options">···</button></td></tr>`).join('')}</tbody></table></div>`;
}
function renderSideStack(live){
 const review=live.flatMap(v=>v.bookings.filter(b=>b.needsReview).map(b=>({v,b}))).slice(0,3);
 const agenda=sortedVisits(live.filter(v=>v.startDate&&v.status!=='Completed'&&v.status!=='Cancelled')).slice(0,3);
 return `<aside class="side-stack"><section class="panel review-panel"><div class="panel-head"><div><h2 class="panel-title">Needs your attention</h2><p class="panel-caption">${review.length?`${reviewCount({bookings:live.flatMap(v=>v.bookings)})} bookings need a look`:'All clear for now'}</p></div><button class="small-link" data-action="needs-review">View all</button></div><div class="review-list">${review.length?review.map(({v,b})=>`<div class="review-item" data-open-visit="${v.id}" data-open-tab="${b.type==='Flight'?'Flights':b.type==='Hotel'?'Hotels':b.type==='Transportation'?'Transportation':b.type==='Restaurant'?'Restaurants':'Activities'}"><i class="review-indicator"></i><div><strong>${esc(b.name)}</strong><p>${esc(v.name)} · ${esc(b.reviewReason||'Review booking details')}</p></div><span class="review-arrow">›</span></div>`).join(''):`<div class="agenda-empty">Any booking flags will appear here.</div>`}</div></section><section class="panel agenda-panel"><div class="panel-head"><div><h2 class="panel-title">Coming up</h2><p class="panel-caption">The next dates on your calendar</p></div><span class="stat-icon blue">◷</span></div>${agenda.length?agenda.map(v=>`<div class="agenda-day" data-open-visit="${v.id}"><div class="agenda-date"><b>${fmtDate(v.startDate,{day:'numeric'})}</b><span>${fmtDate(v.startDate,{month:'short'})}</span></div><div class="agenda-copy"><strong>${esc(v.name)}</strong><small>${esc(v.city||'Destination TBD')} · ${esc(personName(v.lead).split(' ')[0])}</small></div><i class="agenda-mark"></i></div>`).join(''):`<div class="agenda-empty">No visits scheduled yet.</div>`}</section></aside>`;
}
function renderQuickGuide(){return `<section class="panel"><div class="panel-head"><div><h2 class="panel-title">A little more room</h2><p class="panel-caption">Your visits stay organized here</p></div></div><div class="review-list"><div class="review-item"><i class="review-indicator" style="background:#8da89a;box-shadow:0 0 0 4px #edf4ef"></i><div><strong>Everything in one place</strong><p>Guests, bookings and trip details, all together.</p></div></div><div class="review-item"><i class="review-indicator" style="background:#92aab8;box-shadow:0 0 0 4px #eff4f7"></i><div><strong>Pick up where you left off</strong><p>Archived plans are easy to restore anytime.</p></div></div></div></section>`;}
function renderCalendar(visits){
 const month=new Date(page.month.getFullYear(),page.month.getMonth(),1),monthEnd=new Date(month.getFullYear(),month.getMonth()+1,0),offset=(month.getDay()+6)%7,start=new Date(month);start.setDate(month.getDate()-offset);const cells=[];for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);cells.push(d);}
 const ymd=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10);
 return `<div class="calendar-panel"><div class="calendar-head"><h2>${new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric'}).format(month)}</h2><div class="calendar-nav"><button data-month="prev">‹</button><button data-month="today">Today</button><button data-month="next">›</button></div></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="calendar-day-label">${d}</div>`).join('')}${cells.map(d=>{const date=ymd(d),events=visits.filter(v=>v.startDate&&v.endDate&&date>=v.startDate&&date<=v.endDate);return `<div class="calendar-day ${d.getMonth()!==month.getMonth()?'outside':''} ${date===todayISO()?'today':''}"><span class="calendar-day-number">${d.getDate()}</span>${events.slice(0,2).map(v=>`<div class="calendar-event ${v.status.toLowerCase().replaceAll(' ','-')}" data-open-visit="${v.id}">${esc(v.name)}</div>`).join('')}${events.length>2?`<div class="calendar-event">+${events.length-2} more</div>`:''}</div>`;}).join('')}</div><div class="calendar-legend"><span><i class="legend-dot"></i>Upcoming</span><span><i class="legend-dot" style="background:#c4a568"></i>Planning</span><span><i class="legend-dot" style="background:#66a786"></i>In progress</span></div></div>`;
}
function renderSettings(){return `<section class="panel" style="padding:24px;max-width:760px"><p class="eyebrow">LOCAL DEMO</p><h2 class="panel-title" style="font-size:16px">Workspace settings</h2><p class="page-subtitle" style="line-height:1.7;max-width:620px">This MVP runs entirely in your browser. Visit information is saved in local storage on this device. Authentication, invitations, email delivery and shared server storage are not connected in this local prototype.</p><div class="section-title-row"><div><h3>Demo data</h3><p>Reset the browser workspace back to the original sample visits.</p></div><button class="danger-button" data-action="reset-demo">Reset demo data</button></div><div class="notice-banner"><strong>Prototype access:</strong> Use the “View as” control in the top bar to preview the Super Admin, VP or Sales experience. Role changes are for demonstration only and are not server-enforced permissions.</div></section>`;}

function renderDetail(){
  const v=state.visits.find(x=>x.id===page.visitId);if(!v||!canView(v)){page.name='overview';page.visitId=null;return renderDashboard();}
 document.getElementById('breadcrumbCurrent').textContent=v.name;
 const closed=['Completed','Cancelled'].includes(v.status),editable=canEdit(v), tabs=['Overview','Guests','Flights','Hotels','Transportation','Restaurants','Activities','Activity Log'];
 const bookingTotal=v.bookings.length,peopleCount=v.guests.filter(g=>g.status!=='Cancelled').length;
  appContent.innerHTML=`<div class="detail-top"><button class="back-link" data-action="${v.archived?'archives':'all-visits'}">← &nbsp;${v.archived?'Archived visits':'All visits'}</button><div class="detail-actions">${state.role==='SUPER_ADMIN'&&!v.archived?`<button class="quiet-button" data-action="archive-visit" data-id="${v.id}">Archive</button>`:''}${editable?`<button class="secondary-button" data-action="edit-visit" data-id="${v.id}">Edit visit</button>`:''}${state.role==='SUPER_ADMIN'&&v.archived?`<button class="secondary-button" data-action="restore-visit" data-id="${v.id}">Restore visit</button>`:''}</div></div>
    ${v.archived?`<div class="notice-banner archive-banner">This visit is archived. All of its plans, documents and activity remain available.</div>`:''}
    <section class="visit-hero"><div class="hero-art art-${esc(v.theme||'terracotta')}"></div><div class="visit-heading"><p class="eyebrow">CUSTOMER VISIT</p><h1>${esc(v.name)}</h1><div class="visit-subline"><span>${esc(fmtRange(v.startDate,v.endDate))}</span><span class="dot-divider">·</span><span>${esc(v.city?`${v.city}, ${v.country}`:'Destination to be confirmed')}</span><span class="dot-divider">·</span>${statusPill(v.status)}</div></div><div class="detail-meta"><span class="meta-chip">Lead VP ${personAvatar(v.lead)} <b>${esc(personName(v.lead).split(' ')[0])}</b></span><span class="meta-chip"><b>${peopleCount}</b> guests</span></div></section>
    ${closed&&state.role!=='SUPER_ADMIN'?`<p class="access-note">This ${v.status.toLowerCase()} visit is read-only for VPs and Sales.</p>`:''}
    <nav class="tab-bar">${tabs.map(t=>{const type=({Flights:'Flight',Hotels:'Hotel',Transportation:'Transportation',Restaurants:'Restaurant',Activities:'Activity'})[t];return `<button class="tab-button ${page.tab===t?'active':''}" data-tab="${t}">${t==='Activity Log'?'Activity log':t}${t==='Guests'?`<span class="tab-count">${v.guests.length}</span>`:type?`<span class="tab-count">${v.bookings.filter(b=>b.type===type).length}</span>`:''}</button>`;}).join('')}</nav>
    <div class="detail-content">${renderDetailTab(v)}</div>`;
}
function renderDetailTab(v){
 if(page.tab==='Overview')return renderOverview(v);
 if(page.tab==='Guests')return renderGuests(v);
 if(page.tab==='Activity Log')return renderActivity(v);
 const type=page.tab==='Flights'?'Flight':page.tab==='Hotels'?'Hotel':page.tab==='Transportation'?'Transportation':page.tab==='Restaurants'?'Restaurant':'Activity';
 return renderBookings(v,type);
}
function renderOverview(v){
 const fields=[['Destination',v.city?`${v.city}, ${v.country}`:'Not set'],['Start date',fmtDate(v.startDate,{month:'long',day:'numeric',year:'numeric'})],['End date',fmtDate(v.endDate,{month:'long',day:'numeric',year:'numeric'})],['Status',v.status],['Lead VP',personName(v.lead)],['Collaborators',v.collaborators.length?v.collaborators.map(personName).join(', '):'None yet'],['Sales team',v.sales.length?v.sales.map(personName).join(', '):'None yet'],['Guests',`${v.guests.filter(g=>g.status!=='Cancelled').length} active guests`],['Bookings',`${v.bookings.length} total bookings`]];
 return `<div class="overview-grid"><section class="detail-panel"><div class="detail-panel-head"><h3>Visit information</h3><span>${canEdit(v)?`<button class="small-link" data-action="edit-visit" data-id="${v.id}">Edit details</button>`:''}</span></div><div class="info-grid">${fields.map(([k,val])=>`<div class="info-item"><div class="info-label">${k}</div><div class="info-value ${val==='Not set'||val==='None yet'?'subtle':''}">${esc(val)}</div></div>`).join('')}</div>${state.role==='SUPER_ADMIN'?`<div class="detail-panel-head" style="border-top:1px solid #f0f1ee"><h3>Visit status</h3><span>Managed by Monserrat</span></div><div style="padding:0 17px 15px"><button class="secondary-button" data-action="change-visit-status" data-id="${v.id}">Change status · ${esc(v.status)} ↗</button></div>`:''}</section>
 <section class="detail-panel"><div class="detail-panel-head"><h3>Booking progress</h3><span>${v.bookings.length} total bookings</span></div><div class="progress-list">${bookingTypes.map(t=>{const counts=categoryCounts(v,t),pct=progress(v,t);return `<div class="progress-row"><div class="progress-head"><strong>${iconFor(t)} &nbsp;${t==='Transportation'?'Ground transport':t==='Restaurant'?'Restaurants':t==='Activity'?'Activities':t+'s'}</strong><span>${pct===null?'N/A':pct+'%'}</span></div>${pct===null?`<div class="progress-bar"><i style="width:0"></i></div>`:`<div class="progress-bar"><i style="width:${pct}%"></i></div>`}<div class="progress-foot">${counts.map(([s,n])=>n?`<span class="${s==='Done'?'done':s==='To Do'?'todo':''}">${s} ${n}</span>`:'').filter(Boolean).join('')||'<span>No active bookings</span>'}${counts.find(([s])=>s==='Cancelled')[1]?`<span>Cancelled ${counts.find(([s])=>s==='Cancelled')[1]}</span>`:''}</div></div>`;}).join('')}</div></section></div>
 <div class="section-title-row"><div><h3>Latest bookings</h3><p>A snapshot of the trip logistics</p></div><button class="small-link" data-tab="Guests">View guests →</button></div>${renderBookingGrid(v,v.bookings.slice(0,4))}`;
}
function renderGuests(v){const editable=canEdit(v);return `<div class="section-title-row"><div><h3>Visit guests <span class="tab-count">${v.guests.length}</span></h3><p>Keep customer details and attendance up to date.</p></div>${editable?`<button class="primary-button" data-action="new-guest"><span class="plus">+</span> Add guest</button>`:''}</div>${!v.guests.length?`<div class="empty-state panel"><div class="empty-symbol">♧</div><h3>No guests yet</h3><p>Add the people attending this customer visit.</p>${editable?`<button class="primary-button" data-action="new-guest"><span class="plus">+</span> Add guest</button>`:''}</div>`:`<div class="table-list"><div class="data-row data-row-head"><div>Guest</div><div>Company</div><div>Attendance</div><div>Email</div><div></div></div>${v.guests.map(g=>`<div class="data-row"><div class="guest-primary">${guestAvatar(g)}<span><strong>${esc(g.firstName)} ${esc(g.lastName)}</strong><small class="guest-contact">${g.status==='Cancelled'?'Cancelled guest':'Guest profile'}</small></span></div><div>${esc(g.company||'—')}</div><div>${`<select class="filter-select guest-status-select" data-guest-status="${g.id}" ${!editable?'disabled':''}>${['Invited','Confirmed','Cancelled'].map(s=>`<option ${g.status===s?'selected':''}>${s}</option>`).join('')}</select>`}</div><div>${esc(g.email||'—')}</div><div>${editable?`<span class="guest-actions"><button class="inline-action" data-action="edit-guest" data-id="${g.id}" aria-label="Edit guest" title="Edit guest">Edit</button><button class="inline-action guest-remove" data-action="remove-guest" data-id="${g.id}" aria-label="Remove guest" title="Remove guest">×</button></span>`:''}</div></div>${g.notes?`<div class="guest-note"><strong>Notes</strong><span>${esc(g.notes)}</span></div>`:''}`).join('')}</div>`}`;}
function renderBookings(v,type){const list=v.bookings.filter(b=>b.type===type),editable=canEdit(v);return `<div class="section-title-row"><div><h3>${type==='Transportation'?'Ground transportation':type==='Restaurant'?'Restaurant reservations':type==='Activity'?'Planned activities':`${type}s`} <span class="tab-count">${list.length}</span></h3><p>${type==='Flight'?'Guest itineraries and flight segments':type==='Hotel'?'Shared hotel bookings and individual stays':type==='Transportation'?'Airport transfers and ground transport':type==='Restaurant'?'Dining plans and reservations':'Experiences planned for your guests'}</p></div>${editable?`<button class="primary-button" data-action="new-booking" data-type="${type}"><span class="plus">+</span> Add ${type==='Transportation'?'transport':type.toLowerCase()}</button>`:''}</div>${type==='Flight'&&list.length?`<div class="notice-banner">Flight information is entered manually. Add each segment and assign everyone sharing this itinerary.</div>`:''}${!list.length?`<div class="empty-state panel"><div class="empty-symbol">${iconFor(type)}</div><h3>No ${type.toLowerCase()} bookings yet</h3><p>Add plans as details become available. You can update booking progress at any time.</p>${editable?`<button class="primary-button" data-action="new-booking" data-type="${type}"><span class="plus">+</span> Add ${type==='Transportation'?'transport':type.toLowerCase()}</button>`:''}</div>`:renderBookingGrid(v,list,type)}`;}
function renderBookingGrid(v,list){return `<div class="booking-grid">${list.map(b=>{const guests=b.guestIds.map(id=>v.guests.find(g=>g.id===id)).filter(Boolean);const location=b.location||(b.details?.from&&b.details?.to?`${b.details.from} → ${b.details.to}`:'');return `<article class="booking-card"><div class="booking-card-top"><div class="booking-glyph ${b.type.toLowerCase()}">${iconFor(b.type)}</div><div class="booking-name"><strong>${esc(b.name)}</strong><small>${esc(location||'Details to be confirmed')}${b.date?` · ${esc(fmtDate(b.date))}`:''}${b.time?` · ${esc(b.time)}`:''}</small></div>${statusPill(b.status)}</div>${b.type==='Flight'&&b.details?.segments?.length?`<div class="booking-route">${b.details.segments.map(s=>`<div class="route-segment"><span>${esc(s.from||'—')}</span><i></i><span>${esc(s.to||'—')}</span><small>${esc(s.flight||'Flight TBD')} · ${esc(s.date?fmtDate(s.date):'Date TBD')}</small></div>`).join('')}</div>`:''}${b.type==='Hotel'&&guests.length?`<div class="stay-summary">${guests.map(g=>{const stay=b.details.stays?.[g.id]||{checkIn:b.details.checkIn||b.date,checkOut:b.details.checkOut||b.endDate};return `<div><span>${esc(g.firstName)} ${esc(g.lastName)}</span><small>${stay.checkIn?fmtDate(stay.checkIn):'Check-in TBD'} – ${stay.checkOut?fmtDate(stay.checkOut):'Check-out TBD'}</small></div>`;}).join('')}</div>`:''}<div class="booking-card-foot"><span class="guest-avatars">${guests.slice(0,4).map(guestAvatar).join('')}${guests.length>4?`<span class="mini-avatar">+${guests.length-4}</span>`:''}${!guests.length?'<span>No guests assigned</span>':''}</span><span>${guests.length} ${guests.length===1?'guest':'guests'} ${b.details?.reference?`· Ref ${esc(b.details.reference)}`:''}</span><div class="booking-actions"><button class="booking-edit" data-action="edit-booking" data-id="${b.id}" aria-label="Edit booking">Edit</button>${state.role==='SUPER_ADMIN'?`<button class="booking-delete" type="button" data-action="delete-booking" data-visit-id="${v.id}" data-booking-id="${b.id}" aria-label="Delete ${esc(b.type.toLowerCase())} booking">Delete</button>`:''}</div></div>${b.attachments?.length?`<div class="attachment-list">${b.attachments.map(a=>`<div class="attachment-item"><span>▧</span><a href="${esc(a.data)}" download="${esc(a.name)}">${esc(a.name)}</a>${canEdit(v)?`<button data-action="remove-attachment" data-id="${b.id}" data-attachment="${a.id}" aria-label="Remove attachment">×</button>`:''}</div>`).join('')}</div>`:''}${b.needsReview?`<div class="booking-needs-review"><span>◉ &nbsp;Needs review · ${esc(b.reviewReason||'Check details')}</span>${state.role==='SUPER_ADMIN'?`<button data-action="clear-review" data-id="${b.id}">Mark reviewed</button>`:''}</div>`:''}</article>`;}).join('')}</div>`;}
function renderActivity(v){return `<div class="section-title-row"><div><h3>Activity log</h3><p>A record of the changes made to this visit.</p></div></div>${v.activity.length?`<div class="log-list">${v.activity.map(a=>`<div class="log-entry"><span class="log-dot">${esc((a.actor||'A')[0])}</span><div class="log-copy"><strong>${esc(a.action)}</strong><p>${esc(a.detail)}</p><time>${esc(a.actor)} · ${new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(a.at))}</time></div></div>`).join('')}</div>`:`<div class="empty-state panel"><div class="empty-symbol">◷</div><h3>No activity yet</h3><p>Important changes will appear here.</p></div>`}`;}

function openVisit(id,tab){const visit=state.visits.find(v=>v.id===id);if(!visit||!canView(visit)){toast('You do not have access to this visit.',true);return;}page.name='detail';page.visitId=id;if(tab)page.tab=tab;else page.tab='Overview';render();}
function render(){document.getElementById('roleSelect').value=state.role||'SUPER_ADMIN';if(page.name==='detail')renderDetail();else renderDashboard();updateNav();}
function toast(message,error=false){const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=message;document.getElementById('toastRegion').append(el);setTimeout(()=>el.remove(),3000);}
function openModal(title,body,footer,submit,wide=false,eyebrow='AXIS VISITS'){document.getElementById('modalTitle').textContent=title;document.getElementById('modalEyebrow').textContent=eyebrow;document.getElementById('modalBody').innerHTML=body;document.getElementById('modalFooter').innerHTML=footer;document.querySelector('.modal').classList.toggle('wide',wide);document.getElementById('modalBackdrop').hidden=false;modalSubmit=submit;const first=document.querySelector('#modalBody input:not([type=hidden]),#modalBody select');if(first)setTimeout(()=>first.focus(),40);}
function closeModal(){document.getElementById('modalBackdrop').hidden=true;modalSubmit=null;}
function field(name,label,value='',type='text',optional=true,attrs=''){return `<div class="form-field"><label for="${name}">${label} ${optional?'<span class="optional">Optional</span>':''}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value||'')}" ${attrs}></div>`;}
function selectField(name,label,options,value='',optional=true){return `<div class="form-field"><label for="${name}">${label} ${optional?'<span class="optional">Optional</span>':''}</label><select id="${name}" name="${name}">${options.map(o=>`<option value="${esc(typeof o==='string'?o:o.value)}" ${value===(typeof o==='string'?o:o.value)?'selected':''}>${esc(typeof o==='string'?o:o.label)}</option>`).join('')}</select></div>`;}
function showNewVisit(){if(state.role!=='SUPER_ADMIN')return toast('Only Monserrat can create official visits.',true);const vps=people.filter(p=>p.role==='VP');openModal('Create a visit',`<form id="modalForm"><div class="form-grid"><div class="form-field full"><label for="name">Visit name <span style="color:#d94f37">*</span></label><input id="name" name="name" placeholder="e.g. Montreal Client Visit" required maxlength="90"></div>${selectField('lead','Lead VP',vps.map(p=>({value:p.id,label:p.name})),vps[0].id,false)}<p class="form-help" style="grid-column:1/-1;margin:0">You can fill in the destination and dates as plans take shape.</p></div></form>`,`<button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit" form="modalForm">Create visit</button>`,data=>{const v={id:uid(),name:data.name.trim(),city:'',country:'',startDate:'',endDate:'',status:'Planning',lead:data.lead,collaborators:[],sales:[],archived:false,theme:['terracotta','blue','sage','night'][state.visits.length%4],guests:[],bookings:[],activity:[]};log(v,'Visit created',`Created this visit and assigned ${personName(v.lead)} as Lead VP.`);state.visits.unshift(v);persist();closeModal();openVisit(v.id);toast('Visit created · Planning');});}
function showEditVisit(v){const vps=people.filter(p=>p.role==='VP'),editable=canEdit(v);if(!editable){toast('You do not have permission to edit this visit.',true);return;}const collabs=people.filter(p=>p.role==='VP'&&p.id!==v.lead);const sales=people.filter(p=>p.role==='SALES');openModal('Edit visit details',`<form id="modalForm"><div class="form-grid"><div class="form-field full"><label for="name">Visit name <span style="color:#d94f37">*</span></label><input id="name" name="name" value="${esc(v.name)}" required></div><div class="form-divider">Destination & dates</div>${field('city','City',v.city)}${field('country','Country',v.country)}${field('startDate','Start date',v.startDate,'date')}${field('endDate','End date',v.endDate,'date')}<div class="form-divider">Visit team</div>${selectField('lead','Lead VP',vps.map(p=>({value:p.id,label:p.name})),v.lead,false)}<div class="form-field"><label>Collaborating VPs <span class="optional">Optional</span></label><div class="check-group">${collabs.map(p=>`<label class="check-option"><input name="collaborators" value="${p.id}" type="checkbox" ${v.collaborators.includes(p.id)?'checked':''}>${esc(p.name.split(' ')[0])}</label>`).join('')}</div></div><div class="form-field full"><label>Sales team <span class="optional">Optional</span></label><div class="check-group">${sales.map(p=>`<label class="check-option"><input name="sales" value="${p.id}" type="checkbox" ${v.sales.includes(p.id)?'checked':''}>${esc(p.name)}</label>`).join('')}</div></div></div></form>`,`<button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit" form="modalForm">Save changes</button>`,data=>{if(data.startDate&&data.endDate&&data.endDate<data.startDate){toast('End date must be the same as or later than start date.',true);return false;}const oldName=v.name,oldDates=`${v.startDate}|${v.endDate}`;Object.assign(v,{name:data.name.trim(),city:data.city.trim(),country:data.country.trim(),startDate:data.startDate,endDate:data.endDate,lead:data.lead,collaborators:data.collaborators||[],sales:data.sales||[]});if(oldName!==v.name)log(v,'Visit details updated',`Visit name changed to ${v.name}.`);if(oldDates!==`${v.startDate}|${v.endDate}`){log(v,'Visit dates updated',`Dates changed to ${fmtRange(v.startDate,v.endDate)}.`);for(const b of v.bookings){const first=b.date||b.details?.checkIn, last=b.endDate||b.details?.checkOut||first;if(first&&((v.startDate&&first<v.startDate)||(v.endDate&&last>v.endDate))){b.needsReview=true;b.reviewReason='Booking is outside the updated visit dates';}}}persist();closeModal();render();toast('Visit details saved');});}
function showVisitStatus(v){if(state.role!=='SUPER_ADMIN')return;const options=visitStatuses;openModal('Change visit status',`<form id="modalForm"><div class="form-grid"><p class="form-help" style="grid-column:1/-1;margin:0">Choose the current planning stage for <b>${esc(v.name)}</b>.</p><div class="form-field full"><label for="status">Visit status</label><select id="status" name="status">${options.map(s=>`<option ${v.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div id="statusError" class="form-error" hidden></div></div></form>`,`<button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit" form="modalForm">Save status</button>`,data=>{const error=document.getElementById('statusError');if(data.status==='Upcoming'&&(!v.city||!v.country||!v.startDate||!v.endDate)){error.hidden=false;error.innerHTML=`To move this visit to Upcoming, complete: ${[!v.city?'destination city':'',!v.country?'destination country':'',!v.startDate?'start date':'',!v.endDate?'end date':''].filter(Boolean).join(', ')}. <button type="button" class="small-link" data-action="edit-visit" data-id="${v.id}">Add details</button>`;return false;}if(data.status!==v.status){const old=v.status;v.status=data.status;log(v,'Visit status changed',`${old} → ${data.status}.`);}persist();closeModal();render();toast('Visit status updated');});}
function showNewGuest(v){if(!canEdit(v))return toast('This visit is read-only.',true);openModal('Add a guest',`<form id="modalForm"><div class="form-grid">${field('firstName','First name','','text',false,'required')}${field('lastName','Last name','','text',false,'required')}${field('email','Email','','email')}${field('company','Company')}<div class="form-field full"><label for="notes">Notes <span class="optional">Optional</span></label><textarea id="notes" name="notes" placeholder="Dietary needs, context, or other details"></textarea></div></div></form>`,`<button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit" form="modalForm">Add guest</button>`,data=>{const g={id:uid(),firstName:data.firstName.trim(),lastName:data.lastName.trim(),email:data.email.trim(),company:data.company.trim(),status:'Invited',notes:data.notes.trim()};v.guests.push(g);log(v,'Guest added',`Added ${g.firstName} ${g.lastName}.`);persist();closeModal();render();toast('Guest added');});}
function showEditGuest(v,g){if(!canEdit(v))return toast('This visit is read-only.',true);openModal('Edit guest details',`<form id="modalForm"><div class="form-grid">${field('firstName','First name',g.firstName,'text',false,'required')}${field('lastName','Last name',g.lastName,'text',false,'required')}${field('email','Email',g.email,'email')}${field('company','Company',g.company)}${selectField('status','Attendance status',['Invited','Confirmed','Cancelled'],g.status,false)}<div class="form-field full"><label for="notes">Notes <span class="optional">Optional</span></label><textarea id="notes" name="notes" placeholder="Dietary needs, context, or other details">${esc(g.notes||'')}</textarea></div></div></form>`,`<button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit" form="modalForm">Save guest</button>`,data=>{const previousName=`${g.firstName} ${g.lastName}`,oldStatus=g.status;Object.assign(g,{firstName:data.firstName.trim(),lastName:data.lastName.trim(),email:data.email.trim(),company:data.company.trim(),notes:data.notes.trim()});log(v,'Guest details updated',`Updated ${previousName} to ${g.firstName} ${g.lastName}.`);if(data.status!==oldStatus){closeModal();changeGuest(v,g,data.status);return;}persist();closeModal();render();toast('Guest details saved');});}
function changeGuest(v,guest,status){if(!canEdit(v))return;const old=guest.status;guest.status=status;if(status==='Cancelled'&&old!=='Cancelled'){const affected=v.bookings.filter(b=>b.guestIds.includes(guest.id));affected.forEach(b=>{b.needsReview=true;b.reviewReason=`${guest.firstName} ${guest.lastName} cancelled their attendance`;});log(v,'Guest cancelled',`${guest.firstName} ${guest.lastName} cancelled. ${affected.length?`${affected.length} associated booking${affected.length===1?'':'s'} flagged Needs Review.`:'No linked bookings found.'}`);persist();render();if(affected.length)openAffectedBookings(v,guest,affected);else toast('Guest marked as cancelled');}else{log(v,'Guest status updated',`${guest.firstName} ${guest.lastName}: ${old} → ${status}.`);persist();render();toast('Guest status updated');}}
function openAffectedBookings(v,g,affected){const map={Flight:'Flights',Hotel:'Hotels',Transportation:'Transportation',Restaurant:'Restaurants',Activity:'Activities'};openModal('Guest cancellation',`<p class="confirmation-copy"><b>${esc(g.firstName)} ${esc(g.lastName)}</b> is linked to these bookings. They remain unchanged and are marked Needs Review for Monserrat.</p><div class="review-list" style="padding:0">${affected.map(b=>`<div class="review-item"><i class="review-indicator"></i><div><strong>${esc(b.name)}</strong><p>${esc(b.type)} · ${esc(b.status)}</p></div><button class="small-link" data-action="close-and-tab" data-tab="${map[b.type]}">View</button></div>`).join('')}</div>`,`<button class="primary-button" data-action="close-modal">Done</button>`,null);}
function confirmRemoveGuest(v,g){openModal('Remove guest',`<p class="confirmation-copy">Remove <b>${esc(g.firstName)} ${esc(g.lastName)}</b> from this visit? Existing bookings will remain in place and this change will be recorded in the activity log.</p>`,`<button class="secondary-button" data-action="close-modal">Keep guest</button><button class="danger-button" data-action="confirm-remove-guest" data-id="${g.id}">Remove guest</button>`,null);}
function stayFields(guests,stays={}){if(!guests.length)return '';return `<div class="form-field full"><label>Individual guest stays <span class="optional">Optional</span></label><div class="stay-list">${guests.map(g=>`<div class="stay-row"><strong>${esc(g.firstName)} ${esc(g.lastName)}</strong><label>In<input type="date" name="stay_checkIn_${g.id}" value="${esc(stays[g.id]?.checkIn||'')}"></label><label>Out<input type="date" name="stay_checkOut_${g.id}" value="${esc(stays[g.id]?.checkOut||'')}"></label></div>`).join('')}</div></div>`;}
function attachmentField(){return `<div class="form-field full"><label>Booking documents <span class="optional">PDF or image · up to 500 KB each</span></label><input type="file" name="attachments" accept="application/pdf,image/*" multiple><span class="form-help">Files are saved in this browser with the visit.</span></div>`;}
function showNewBooking(v,type){if(!canEdit(v))return toast('This visit is read-only.',true);const guests=v.guests.filter(g=>g.status!=='Cancelled');let specific='';if(type==='Flight')specific=`<div class="form-divider">Flight itinerary</div><div class="form-field full"><label>Journey segments <span class="optional">Add each connection</span></label><div id="segments" class="form-grid" style="gap:8px">${segmentMarkup(0)}</div><button type="button" class="segment-add" data-action="add-segment">+ Add another segment</button></div>`;else if(type==='Hotel')specific=`<div class="form-divider">Stay details</div>${field('checkIn','Default check-in date','','date')}${field('checkOut','Default check-out date','','date')}${field('reference','Booking reference')}${stayFields(guests)}`;else if(type==='Transportation')specific=`<div class="form-divider">Transfer details</div>${field('origin','Origin')}${field('destination','Destination')}${field('provider','Provider')}${selectField('vehicle','Vehicle type',['Sedan','SUV','Van','Shuttle','Other'],'Van')}`;else if(type==='Restaurant')specific=`<div class="form-divider">Reservation details</div>${field('partySize','Party size','','number',true,'min="1"')}${field('reservationName','Reservation under')}`;else specific=`<div class="form-divider">Activity details</div>${field('activityType','Activity type')}${field('duration','Duration')}`;
 const guestOptions=guests.length?`<div class="form-field full"><label>Assign guests <span class="optional">Optional</span></label><div class="check-group">${guests.map((g,i)=>`<label class="check-option"><input name="guestIds" type="checkbox" value="${g.id}" ${type==='Flight'&&i===0?'checked':''}>${esc(g.firstName)} ${esc(g.lastName)}</label>`).join('')}</div></div>`:`<div class="form-field full"><label>Assign guests</label><p class="form-help">Add guests first to link them to this booking.</p></div>`;
 openModal(`Add ${type==='Transportation'?'ground transport':type.toLowerCase()}`,`<form id="modalForm" data-type="${type}"><div class="form-grid"><div class="form-field full"><label for="name">${type} name <span style="color:#d94f37">*</span></label><input id="name" name="name" placeholder="${esc(type==='Flight'?'e.g. AC 871 · Montreal to Toronto':type==='Hotel'?'e.g. Hotel William Gray':type==='Transportation'?'e.g. Airport transfer':type==='Restaurant'?'e.g. Dinner at Monarque':'e.g. Axis Studio tour')}" required></div>${field('date',type==='Hotel'?'Booking date':'Date','', 'date')}${field('time','Time','','time')}${field('location',type==='Transportation'?'Route / location':type==='Flight'?'Airport / route':'Location / address')}${canManageBookingStatus()?selectField('status','Booking status',bookingStatuses,'To Do',false):'<input type="hidden" name="status" value="To Do">'}${specific}${guestOptions}${attachmentField()}<div class="form-field full"><label for="notes">Notes <span class="optional">Optional</span></label><textarea id="notes" name="notes" placeholder="Additional booking details"></textarea></div></div></form>`,`<button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit" form="modalForm">Save booking</button>`,data=>{if(type==='Hotel'&&data.checkIn&&data.checkOut&&data.checkOut<data.checkIn){toast('Check-out must be on or after check-in.',true);return false;}const guestIds=data.guestIds||[];const details={};['airline','flightNumber','checkIn','checkOut','reference','origin','destination','provider','vehicle','partySize','reservationName','activityType','duration','notes'].forEach(k=>{if(data[k])details[k]=data[k];});if(type==='Hotel'){details.checkIn=data.checkIn||'';details.checkOut=data.checkOut||'';details.stays={};for(const id of guestIds){const g=v.guests.find(x=>x.id===id);if(data[`stay_checkIn_${id}`]||data[`stay_checkOut_${id}`])details.stays[id]={checkIn:data[`stay_checkIn_${id}`]||data.checkIn||'',checkOut:data[`stay_checkOut_${id}`]||data.checkOut||''};if(g&&details.stays[id]?.checkIn&&details.stays[id]?.checkOut&&details.stays[id].checkOut<details.stays[id].checkIn){toast(`Check-out must be on or after check-in for ${g.firstName}.`,true);return false;}}}if(type==='Flight')details.segments=data.segments||[];const b={id:uid(),type,name:data.name.trim(),status:canManageBookingStatus()?data.status:'To Do',date:data.date||data.checkIn||'',time:data.time||'',location:data.location||'',endDate:data.checkOut||'',guestIds,details,attachments:data.attachments||[],needsReview:false};v.bookings.push(b);log(v,`${type} booking added`,`Added ${b.name} · ${b.status}.`);persist();closeModal();render();toast(`${type} booking added`);},true);}
function segmentMarkup(index,s={}){return `<div class="segment-card" data-segment="${index}"><div class="segment-heading"><div class="segment-title">Segment ${index+1}</div><button type="button" class="segment-remove" data-action="remove-segment" aria-label="Remove segment ${index+1}">Remove</button></div><div class="form-field"><label>From</label><input name="seg_from_${index}" value="${esc(s.from||'')}" placeholder="YUL"></div><div class="form-field"><label>To</label><input name="seg_to_${index}" value="${esc(s.to||'')}" placeholder="YYZ"></div><div class="form-field"><label>Flight no.</label><input name="seg_flight_${index}" value="${esc(s.flight||'')}" placeholder="AC 420"></div><div class="form-field"><label>Date</label><input name="seg_date_${index}" type="date" value="${esc(s.date||'')}"></div><div class="form-field"><label>Departure time</label><input name="seg_time_${index}" type="time" value="${esc(s.time||'')}"></div><div class="form-field"><label>Airline</label><input name="seg_airline_${index}" value="${esc(s.airline||'')}" placeholder="Air Canada"></div></div>`;}
function renumberSegments(wrap){[...wrap.querySelectorAll('[data-segment]')].forEach((card,index)=>{card.dataset.segment=index;const title=card.querySelector('.segment-title'),remove=card.querySelector('.segment-remove');if(title)title.textContent=`Segment ${index+1}`;if(remove)remove.setAttribute('aria-label',`Remove segment ${index+1}`);card.querySelectorAll('[name^="seg_"]').forEach(input=>{const match=input.name.match(/^seg_(from|to|flight|date|time|airline)_\d+$/);if(match)input.name=`seg_${match[1]}_${index}`;});});}
function showEditBooking(v,b){if(!canEdit(v))return toast('This visit is read-only.',true);const type=b.type, editableStatus=canManageBookingStatus(),stayMarkup=type==='Hotel'?stayFields(v.guests.filter(g=>g.status!=='Cancelled'),b.details.stays||{}):'',segmentInputs=type==='Flight'?`<div class="form-field full"><label>Journey segments <span class="optional">Add each connection</span></label><div id="segments" class="form-grid" style="gap:8px">${(b.details.segments?.length?b.details.segments:[{}]).map((s,i)=>segmentMarkup(i,s)).join('')}</div><button type="button" class="segment-add" data-action="add-segment">+ Add another segment</button></div>`:'';const attached=(b.attachments||[]).map(a=>`<div class="attachment-item"><span>▧</span><a href="${esc(a.data)}" download="${esc(a.name)}">${esc(a.name)}</a><button type="button" data-action="remove-attachment" data-id="${b.id}" data-attachment="${a.id}">×</button></div>`).join('');openModal('Booking details',`<form id="modalForm" data-type="${type}"><div class="form-grid"><div class="form-field full"><label for="name">Booking name</label><input id="name" name="name" value="${esc(b.name)}" required></div>${field('date','Date',b.date,'date')}${field('time','Time',b.time,'time')}${field('location','Location',b.location)}${editableStatus?selectField('status','Booking status',bookingStatuses,b.status,false):`<div class="form-field"><label>Booking status</label><input value="${esc(b.status)}" disabled></div>`}${type==='Hotel'?`${field('checkIn','Default check-in date',b.details.checkIn||b.date,'date')}${field('checkOut','Default check-out date',b.details.checkOut||b.endDate,'date')}${field('reference','Booking reference',b.details.reference||'')}${stayMarkup}`:''}${type==='Transportation'?`${field('origin','Origin',b.details.origin||'')}${field('destination','Destination',b.details.destination||'')}${field('provider','Provider',b.details.provider||'')}${field('vehicle','Vehicle type',b.details.vehicle||'')}`:''}${type==='Restaurant'?field('partySize','Party size',b.details.partySize||'','number',true,'min="1"'):''}${type==='Activity'?`${field('activityType','Activity type',b.details.activityType||'')}${field('duration','Duration',b.details.duration||'')}`:''}${segmentInputs}<div class="form-field full"><label>Assigned guests</label><div class="check-group">${v.guests.filter(g=>g.status!=='Cancelled').map(g=>`<label class="check-option"><input name="guestIds" type="checkbox" value="${g.id}" ${b.guestIds.includes(g.id)?'checked':''}>${esc(g.firstName)} ${esc(g.lastName)}</label>`).join('')}</div></div>${attached?`<div class="form-field full"><label>Attached documents</label><div class="attachment-list">${attached}</div></div>`:''}${attachmentField()}<div class="form-field full"><label for="notes">Notes <span class="optional">Optional</span></label><textarea name="notes" id="notes">${esc(b.details.notes||'')}</textarea></div></div></form>`,`<button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit" form="modalForm">Save changes</button>`,data=>{if(type==='Hotel'&&data.checkIn&&data.checkOut&&data.checkOut<data.checkIn){toast('Check-out must be on or after check-in.',true);return false;}const old=`${b.date}|${b.endDate}`;Object.assign(b,{name:data.name.trim(),date:data.date||data.checkIn||'',time:data.time||'',location:data.location||'',guestIds:data.guestIds||[]});if(editableStatus)b.status=data.status;b.details={...b.details,notes:data.notes||''};['checkIn','checkOut','reference','origin','destination','provider','vehicle','partySize','activityType','duration'].forEach(k=>{if(data[k])b.details[k]=data[k];});if(type==='Flight')b.details.segments=data.segments||[];if(type==='Hotel'){b.endDate=data.checkOut||'';b.details.checkIn=data.checkIn||'';b.details.checkOut=data.checkOut||'';b.details.stays={};for(const id of b.guestIds){const g=v.guests.find(x=>x.id===id);if(data[`stay_checkIn_${id}`]||data[`stay_checkOut_${id}`])b.details.stays[id]={checkIn:data[`stay_checkIn_${id}`]||data.checkIn||'',checkOut:data[`stay_checkOut_${id}`]||data.checkOut||''};if(g&&b.details.stays[id]?.checkIn&&b.details.stays[id]?.checkOut&&b.details.stays[id].checkOut<b.details.stays[id].checkIn){toast(`Check-out must be on or after check-in for ${g.firstName}.`,true);return false;}}}b.attachments=[...(b.attachments||[]),...(data.attachments||[])];if(old!==`${b.date}|${b.endDate}`){b.needsReview=false;b.reviewReason='';}log(v,`${type} booking updated`,`Updated ${b.name}.`);persist();closeModal();render();toast('Booking details saved');},true);}
function confirmDeleteBooking(v,b){if(state.role!=='SUPER_ADMIN')return toast('Only Monserrat can delete bookings.',true);openModal('Delete booking?',`<p class="confirmation-copy"><b>${esc(b.name)}</b> and its itinerary, guest assignments, notes and attached documents will be deleted from <b>${esc(v.name)}</b>. This cannot be undone.</p>`,`<button class="secondary-button" data-action="close-modal">Keep booking</button><button class="danger-button" data-action="confirm-delete-booking" data-visit-id="${v.id}" data-booking-id="${b.id}">Delete booking</button>`,null);}
function deleteBooking(v,id){if(state.role!=='SUPER_ADMIN')return toast('Only Monserrat can delete bookings.',true);const index=v.bookings.findIndex(b=>b.id===id);if(index<0)return;const [booking]=v.bookings.splice(index,1);log(v,`${booking.type} booking deleted`,`Deleted ${booking.name}.`);persist();closeModal();render();toast(`${booking.type} booking deleted`);}
function clearReview(v,b){if(state.role!=='SUPER_ADMIN')return toast('Only Monserrat can clear Needs Review.',true);b.needsReview=false;b.reviewReason='';log(v,'Needs Review cleared',`Reviewed ${b.name}.`);persist();render();toast('Booking marked as reviewed');}
function archiveVisit(v,restore=false){if(state.role!=='SUPER_ADMIN')return toast('Only Monserrat can archive visits.',true);if(restore){v.archived=false;log(v,'Visit restored','Restored this visit to the active dashboard.');persist();page.name='detail';render();toast('Visit restored');return;}openModal('Archive this visit?',`<p class="confirmation-copy"><b>${esc(v.name)}</b> will leave the main dashboard. Its bookings, guests and activity will stay saved, and you can restore it anytime.</p>`,`<button class="secondary-button" data-action="close-modal">Keep active</button><button class="danger-button" data-action="confirm-archive" data-id="${v.id}">Archive visit</button>`,null);}
function resetDemo(){openModal('Reset demo workspace?',`<p class="confirmation-copy">This replaces your locally saved changes with the original sample workspace. This action cannot be undone.</p>`,`<button class="secondary-button" data-action="close-modal">Cancel</button><button class="danger-button" data-action="confirm-reset">Reset workspace</button>`,null);}

function formData(form){const data={};new FormData(form).forEach((val,key)=>{if(key==='attachments')return;if(key==='collaborators'||key==='sales'||key==='guestIds'){(data[key] ||= []).push(val);}else data[key]=val;});const type=form.dataset.type;if(type==='Flight'){const segments=[];form.querySelectorAll('[data-segment]').forEach((card,i)=>{const read=s=>card.querySelector(`[name="seg_${s}_${i}"]`)?.value||'';const seg={from:read('from'),to:read('to'),flight:read('flight'),date:read('date'),time:read('time'),airline:read('airline')};if(Object.values(seg).some(Boolean))segments.push(seg);});data.segments=segments;}return data;}
function fileAsData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({id:uid(),name:file.name,type:file.type,data:reader.result});reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file);});}
document.addEventListener('submit',async e=>{if(e.target.id!=='modalForm')return;e.preventDefault();if(!e.target.reportValidity())return;const form=e.target,button=form.closest('.modal')?.querySelector('button[type=submit]'),originalLabel=button?.textContent;if(button){button.disabled=true;button.textContent='Saving…';}try{const files=[...(form.querySelector('[name="attachments"]')?.files||[])];const tooLarge=files.find(f=>f.size>500*1024);if(tooLarge){toast(`${tooLarge.name} is over the 500 KB local limit.`,true);return;}const allowed=files.filter(f=>f.type==='application/pdf'||f.type.startsWith('image/'));if(allowed.length!==files.length){toast('Choose PDF or image files only.',true);return;}const data=formData(form);data.attachments=await Promise.all(allowed.map(fileAsData));if(modalSubmit){const result=modalSubmit(data);if(result!==false)modalSubmit=null;}else toast('There is no active save action for this form.',true);}catch(err){toast('The changes could not be saved. Try again.',true);}finally{if(button){button.disabled=false;button.textContent=originalLabel;}}});
document.addEventListener('click',e=>{
 const submitButton=e.target.closest('button[type="submit"][form="modalForm"]');if(submitButton){e.preventDefault();document.getElementById('modalForm')?.requestSubmit();return;}
 const open=e.target.closest('[data-open-visit]');if(open){openVisit(open.dataset.openVisit,open.dataset.openTab);return;}
 const view=e.target.closest('[data-view]');if(view){page.view=view.dataset.view;render();return;}
 const tab=e.target.closest('[data-tab]');if(tab){if(tab.dataset.tab==='Guests'&&page.name==='detail')page.tab='Guests';else if(page.name==='detail')page.tab=tab.dataset.tab;render();return;}
 const month=e.target.closest('[data-month]');if(month){if(month.dataset.month==='today')page.month=new Date(new Date().getFullYear(),new Date().getMonth(),1);else page.month.setMonth(page.month.getMonth()+(month.dataset.month==='next'?1:-1));render();return;}
 const btn=e.target.closest('[data-action]');if(!btn)return;const action=btn.dataset.action,v=state.visits.find(x=>x.id===btn.dataset.visitId)||state.visits.find(x=>x.id===btn.dataset.id)||state.visits.find(x=>x.id===page.visitId);
 if(action==='home'){page.name='overview';page.visitId=null;page.onlyReview=false;page.search='';page.filter='All statuses';render();}
 else if(action==='all-visits'){page.name='all-visits';page.visitId=null;page.onlyReview=false;page.search='';page.filter='All statuses';page.view='list';render();}
  else if(action==='needs-review'){page.name='all-visits';page.visitId=null;page.onlyReview=true;page.view='list';page.filter='All statuses';page.search='';render();}
 else if(action==='archives'){page.name='archives';page.onlyReview=false;page.view='list';page.filter='All statuses';page.search='';render();}
 else if(action==='settings'){page.name='settings';render();}
 else if(action==='new-visit')showNewVisit();
 else if(action==='edit-visit'&&v)showEditVisit(v);
 else if(action==='change-visit-status'&&v)showVisitStatus(v);
 else if(action==='new-guest'&&v)showNewGuest(v);
 else if(action==='edit-guest'&&v){const g=v.guests.find(x=>x.id===btn.dataset.id);if(g)showEditGuest(v,g);}
 else if(action==='remove-guest'&&v){const g=v.guests.find(x=>x.id===btn.dataset.id);if(g)confirmRemoveGuest(v,g);}
 else if(action==='confirm-remove-guest'&&v){const g=v.guests.find(x=>x.id===btn.dataset.id);if(g){v.guests=v.guests.filter(x=>x.id!==g.id);log(v,'Guest removed',`Removed ${g.firstName} ${g.lastName} from this visit.`);persist();closeModal();render();toast('Guest removed');}}
 else if(action==='new-booking'&&v)showNewBooking(v,btn.dataset.type);
 else if(action==='edit-booking'&&v){const b=v.bookings.find(x=>x.id===btn.dataset.id);if(b)showEditBooking(v,b);}
 else if(action==='delete-booking'&&v){const b=v.bookings.find(x=>x.id===btn.dataset.bookingId);if(b)confirmDeleteBooking(v,b);}
 else if(action==='confirm-delete-booking'&&v)deleteBooking(v,btn.dataset.bookingId);
 else if(action==='remove-attachment'&&v){const b=v.bookings.find(x=>x.id===btn.dataset.id);if(b&&canEdit(v)){b.attachments=(b.attachments||[]).filter(a=>a.id!==btn.dataset.attachment);log(v,'Booking document removed',`Removed a document from ${b.name}.`);persist();closeModal();render();toast('Document removed');}}
 else if(action==='clear-review'&&v){const b=v.bookings.find(x=>x.id===btn.dataset.id);if(b)clearReview(v,b);}
 else if(action==='archive-visit'&&v)archiveVisit(v);
 else if(action==='confirm-archive'&&v){v.archived=true;log(v,'Visit archived','Archived this visit. All details are retained.');persist();closeModal();page.name='archives';render();toast('Visit archived');}
 else if(action==='restore-visit'&&v)archiveVisit(v,true);
 else if(action==='confirm-reset'){localStorage.removeItem(STORE_KEY);state=seedData();page={name:'overview',visitId:null,tab:'Overview',view:'list',filter:'All statuses',search:'',onlyReview:false,month:new Date(new Date().getFullYear(),new Date().getMonth(),1)};persist();closeModal();render();toast('Demo workspace reset');}
 else if(action==='reset-demo')resetDemo();
 else if(action==='close-modal')closeModal();
 else if(action==='close-and-tab'){closeModal();page.tab=btn.dataset.tab;render();}
 else if(action==='notifications'){const old=document.querySelector('.notification-popover');if(old){old.remove();return;}const box=document.createElement('div');box.className='notification-popover';box.innerHTML=`<h3>Notifications</h3><p>${reviewCount({bookings:state.visits.filter(x=>!x.archived).flatMap(x=>x.bookings)})?`You have ${reviewCount({bookings:state.visits.filter(x=>!x.archived).flatMap(x=>x.bookings)})} booking${reviewCount({bookings:state.visits.filter(x=>!x.archived).flatMap(x=>x.bookings)})===1?'':'s'} flagged Needs Review.`:'You’re all caught up. No new updates.'}</p><button class="small-link" data-action="needs-review">Review flagged bookings →</button>`;document.body.append(box);}
 else if(action==='add-segment'){const wrap=document.getElementById('segments');const index=wrap.querySelectorAll('[data-segment]').length;wrap.insertAdjacentHTML('beforeend',segmentMarkup(index));}
 else if(action==='remove-segment'){const wrap=document.getElementById('segments'),card=btn.closest('[data-segment]');if(!wrap||!card)return;if(wrap.querySelectorAll('[data-segment]').length<=1){toast('A flight itinerary must contain at least one segment.',true);return;}card.remove();renumberSegments(wrap);}
 else if(btn.dataset.rowMenu){const rv=state.visits.find(x=>x.id===btn.dataset.rowMenu);if(rv)openVisit(rv.id);}
});
document.addEventListener('change',e=>{
 if(e.target.id==='roleSelect'){state.role=e.target.value;persist();render();toast(`Viewing as ${e.target.options[e.target.selectedIndex].text}`);return;}
 if(e.target.id==='statusFilter'){page.filter=e.target.value;render();return;}
 if(e.target.id==='reviewFilter'){page.onlyReview=e.target.checked;render();return;}
 if(e.target.matches('[data-guest-status]')){const v=state.visits.find(x=>x.id===page.visitId),g=v?.guests.find(x=>x.id===e.target.dataset.guestStatus);if(v&&g)changeGuest(v,g,e.target.value);}
});
document.addEventListener('input',e=>{if(e.target.id==='visitSearch'){page.search=e.target.value;const pos=e.target.selectionStart;render();const input=document.getElementById('visitSearch');input.focus();input.setSelectionRange(pos,pos);}});
document.getElementById('modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal();});
document.addEventListener('keydown',e=>{const card=e.target.closest?.('.mobile-visit-card[role="button"]');if(card&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openVisit(card.dataset.openVisit);return;}if(e.key==='Escape'){closeModal();document.querySelector('.notification-popover')?.remove();}});
updateNav();render();
